svg.script:
window.onload = function () {
  const NS = "http://www.w3.org/2000/svg";
  const svg = document.documentElement;

  const d = [150, 200, 300, 500];

  const absolute = [
    {
      name: "L₁(s)",
      color: "#1f77b4",
      values: [6.545, 10.307, 17.000, 27.444]
    },
    {
      name: "Lₓ(s)",
      color: "#ff7f0e",
      values: [111.316, 167.829, 266.453, 426.877]
    },
    {
      name: "Goff(s)",
      color: "#2ca02c",
      values: [146.274, 188.367, 280.294, 769.457]
    },
    {
      name: "Gjit(s)",
      color: "#d62728",
      values: [68.672, 87.467, 132.860, 266.820]
    },
    {
      name: "V(s)",
      color: "#9467bd",
      values: [10.964, 14.205, 21.138, 38.979]
    }
  ];

  const normalized = [
    {
      name: "Lₓ/L₁",
      color: "#ff7f0e",
      values: [17.01, 16.28, 15.67, 15.55]
    },
    {
      name: "Goff/L₁",
      color: "#2ca02c",
      values: [22.35, 18.28, 16.49, 28.04]
    },
    {
      name: "Gjit/L₁",
      color: "#d62728",
      values: [10.49, 8.49, 7.82, 9.72]
    },
    {
      name: "V/L₁",
      color: "#9467bd",
      values: [1.68, 1.38, 1.24, 1.42]
    }
  ];

  function el(name, attrs, parent = svg) {
    const element = document.createElementNS(NS, name);

    for (const [key, value] of Object.entries(attrs || {})) {
      element.setAttribute(key, value);
    }

    parent.appendChild(element);
    return element;
  }

  function text(
    content,
    x,
    y,
    className,
    anchor = "middle",
    parent = svg
  ) {
    const element = el(
      "text",
      {
        x: x,
        y: y,
        class: className,
        "text-anchor": anchor
      },
      parent
    );

    element.textContent = content;
    return element;
  }

  function drawPanel(config) {
    const {
      x0,
      y0,
      width,
      height,
      xmin,
      xmax,
      ymax,
      title,
      ylabel,
      xticks,
      yticks,
      series,
      legendRight = false,
      yDecimals = 0
    } = config;

    const right = x0 + width;
    const bottom = y0 + height;

    function X(value) {
      return x0 + ((value - xmin) / (xmax - xmin)) * width;
    }

    function Y(value) {
      return bottom - (value / ymax) * height;
    }

    text(
      title,
      x0 + width / 2,
      35,
      "title"
    );

    // Horizontal gridlines and y-axis labels
    yticks.forEach(value => {
      const y = Y(value);

      el("line", {
        x1: x0,
        y1: y,
        x2: right,
        y2: y,
        class: "grid"
      });

      text(
        value.toFixed(yDecimals),
        x0 - 10,
        y + 4,
        "tick-label",
        "end"
      );
    });

    // Vertical gridlines and x-axis labels
    xticks.forEach(value => {
      const x = X(value);

      el("line", {
        x1: x,
        y1: y0,
        x2: x,
        y2: bottom,
        class: "grid"
      });

      text(
        String(value),
        x,
        bottom + 20,
        "tick-label"
      );
    });

    // Axes
    el("line", {
      x1: x0,
      y1: bottom,
      x2: right,
      y2: bottom,
      class: "axis"
    });

    el("line", {
      x1: x0,
      y1: y0,
      x2: x0,
      y2: bottom,
      class: "axis"
    });

    // Axis labels
    text(
      "Deme Size (d)",
      x0 + width / 2,
      bottom + 48,
      "axis-label"
    );

    const yText = text(
      ylabel,
      x0 - 58,
      y0 + height / 2,
      "axis-label"
    );

    yText.setAttribute(
      "transform",
      `rotate(-90 ${x0 - 58} ${y0 + height / 2})`
    );

    // Legend background
    const legendWidth = legendRight ? 150 : 125;
    const legendX = legendRight
      ? x0 + width - legendWidth - 7
      : x0 + 8;

    el("rect", {
      x: legendX,
      y: y0 + 8,
      width: legendWidth,
      height: series.length * 20 + 15,
      fill: "white",
      opacity: "0.88"
    });

    // Data series and legends
    series.forEach((s, index) => {
      const points = d.map((value, i) => {
        return `${X(value).toFixed(2)},${Y(s.values[i]).toFixed(2)}`;
      }).join(" ");

      el("polyline", {
        points: points,
        class: "series",
        stroke: s.color
      });

      d.forEach((value, i) => {
        el("circle", {
          cx: X(value),
          cy: Y(s.values[i]),
          r: 4,
          fill: s.color,
          class: "point"
        });
      });

      const lx = legendRight
        ? x0 + width - legendWidth + 8
        : x0 + 18;

      const ly = y0 + 20 + index * 20;

      el("line", {
        x1: lx,
        y1: ly - 4,
        x2: lx + 25,
        y2: ly - 4,
        stroke: s.color,
        "stroke-width": 3
      });

      text(
        s.name,
        lx + 32,
        ly,
        "legend",
        "start"
      );
    });
  }

  // Absolute quantities
  drawPanel({
    x0: 80,
    y0: 75,
    width: 450,
    height: 390,
    xmin: 150,
    xmax: 500,
    ymax: 800,
    title: "Time (s) by Deme Size (d)",
    ylabel: "Time (s)",
    xticks: [150, 200, 300, 400, 500],
    yticks: [0, 100, 200, 300, 400, 500, 600, 700, 800],
    yDecimals: 0,
    legendRight: false,
    series: absolute
  });

  // Normalized quantities
  drawPanel({
    x0: 670,
    y0: 75,
    width: 450,
    height: 390,
    xmin: 150,
    xmax: 500,
    ymax: 30,
    title: "Time (L₁ Normalized) by Deme Size (d)",
    ylabel: "Time (L₁ Normalized)",
    xticks: [150, 200, 300, 400, 500],
    yticks: [0, 5, 10, 15, 20, 25, 30],
    yDecimals: 0,
    legendRight: true,
    series: normalized
  });
};
